	RCC->APB1ENR |= (1<<0); //enabled TIM2 clock
	TIM2->PSC = 35999; //dividing the freqn of the pulse of APB1, which is the freqn that timer runs on by default
	TIM2->ARR = 100; //interrupt fires after 1000 pulses i.e 0.1 second
